CREATE TABLE customers (id INTEGER, name TEXT);
CREATE TABLE orders (id INTEGER, customer_id INTEGER, total REAL);
INSERT INTO customers VALUES (1, 'Ana'), (2, 'Bob'), (3, 'Carol');
INSERT INTO orders VALUES (101, 1, 150.0), (102, 1, 200.0), (103, 2, 75.0), (104, 2, 100.0), (105, 3, 250.0);
SELECT c.name, o.id, o.total FROM customers c INNER JOIN orders o ON c.id = o.customer_id ORDER BY c.name, o.id;
